import{_ as e,o as l,c as a,a2 as n}from"./chunks/framework.RycU2wFZ.js";const p=JSON.parse('{"title":"ADR-003: 演进优先级与路线图统合 —— 结算经济性与企业内控 vs. 多链扩展","description":"","frontmatter":{},"headers":[],"relativePath":"specs/adr/003.md","filePath":"specs/adr/003.md","lastUpdated":null}'),s={name:"specs/adr/003.md"};function o(r,t,i,d,c,g){return l(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="adr-003-演进优先级与路线图统合-——-结算经济性与企业内控-vs-多链扩展" tabindex="-1">ADR-003: 演进优先级与路线图统合 —— 结算经济性与企业内控 vs. 多链扩展 <a class="header-anchor" href="#adr-003-演进优先级与路线图统合-——-结算经济性与企业内控-vs-多链扩展" aria-label="Permalink to &quot;ADR-003: 演进优先级与路线图统合 —— 结算经济性与企业内控 vs. 多链扩展&quot;">​</a></h1><blockquote><p><strong>Status</strong>: <strong>Accepted</strong>（已决） <strong>Date</strong>: 2026-11-03 <strong>Deciders</strong>: Project Maintainers <strong>Related</strong>:</p><ul><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/README.md" target="_blank" rel="noreferrer"><code>README.md</code></a> § Roadmap &amp; Delivery Status</li><li><a href="./../gas-models"><code>specs/gas-cost-and-settlement-models.md</code></a>（Gas 经济模型与演进路线）</li><li><a href="https://github.com/open-agentpay/AgentPay/blob/main/specs/currency-and-multichain-spec.md" target="_blank" rel="noreferrer"><code>specs/currency-and-multichain-spec.md</code></a>（多链 <code>scheme</code> 抽象扩展草案）</li></ul></blockquote><hr><h2 id="_1-context-problem-statement" tabindex="-1">1. Context &amp; Problem Statement <a class="header-anchor" href="#_1-context-problem-statement" aria-label="Permalink to &quot;1. Context &amp; Problem Statement&quot;">​</a></h2><p>此前项目存在多份分散的历史规划与表述差异，且部分规划带有年份硬编码限制：</p><ol><li>Gas Mode 2（动态 Gas 加价分摊）与 Mode 3（批量聚合 / 状态通道）。</li><li>可插拔 <code>scheme</code> 多链与多资产扩展草案。</li><li>企业内控安全、HITL 人机协同审批与 AI FinOps。</li></ol><p>按设计规范，文档冲突与演进决策<strong>不得静默择一</strong>，须统合为统一事实来源（Single Source of Truth）。本 ADR 记录该优先级裁决，并正式废除所有基于具体自然年份的旧版临时碎片规划，以统一的优先级阶梯（P0 ~ P3）为主线路线图。</p><p>约束条件：</p><ol><li>工程资源集中优先攻克核心商业与企业生产价值闭环，同一时期保持清晰的主线聚焦。</li><li>现有客户调用量的快速增长对 Gas 与结算成本提出刚性要求。</li><li>企业场景下安全防线（HITL、防套取、预算配额）是落地准入的前提条件。</li></ol><hr><h2 id="_2-options-considered" tabindex="-1">2. Options Considered <a class="header-anchor" href="#_2-options-considered" aria-label="Permalink to &quot;2. Options Considered&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;"><strong>A. 先做结算经济性与企业内控</strong>（Gas Mode 2/3 + HITL/FinOps）</th><th style="text-align:left;"><strong>B. 先做多链扩展</strong>（Solana / 多非 EVM 链）</th></tr></thead><tbody><tr><td style="text-align:left;">直接收益</td><td style="text-align:left;">高频微支付在规模化后仍保毛利；单笔成本降低 95%+；企业生产环境具备合规准入资格</td><td style="text-align:left;">触达新链生态与跨链 Agent 客户</td></tr><tr><td style="text-align:left;">依赖与风险</td><td style="text-align:left;">低。链上逻辑自持，不依赖外部标准变更</td><td style="text-align:left;">中高。需新链的签名方案（非 EIP-3009）、资金安全重审、新 Facilitator 适配</td></tr><tr><td style="text-align:left;">对现有架构的破坏性</td><td style="text-align:left;">低。网关已有结算抽象与对账闭环，以插件化中间件增强</td><td style="text-align:left;"><strong>高</strong>。多链会直接冲击现有 EIP-712/3009 状态机模型</td></tr><tr><td style="text-align:left;">可验证性</td><td style="text-align:left;">强。单笔成本与审批阻断可在现有真实测试链路量化对比</td><td style="text-align:left;">弱。需外部生态客户配合验证需求真实性</td></tr><tr><td style="text-align:left;">优先级评定</td><td style="text-align:left;"><strong>最高（P0 / P1 / P2 核心主线）</strong></td><td style="text-align:left;"><strong>P3 远期探索（视生态需求启动）</strong></td></tr></tbody></table><hr><h2 id="_3-decision" tabindex="-1">3. Decision <a class="header-anchor" href="#_3-decision" aria-label="Permalink to &quot;3. Decision&quot;">​</a></h2><p><strong>采纳方案 A 并统合为主线路线图</strong>：</p><ol><li><strong>统一路线图</strong>：建立权威的主线规划优先级阶梯，废除零散年份规划。</li><li><strong>结算经济性与企业内控并行演进</strong>： <ul><li><strong>P0</strong>：企业人机协同审批（HITL 飞书/企微/钉钉卡片拦截）与安全防套取。</li><li><strong>P1</strong>：AI 财务 FinOps（树状配额与非托管法币对账）与 Gas 模式 2（动态加价分摊）。</li><li><strong>P2</strong>：模式 3（批量聚合 / 状态通道延迟结算）与本地进程外 Sidecar 守护进程。</li><li><strong>P3</strong>：多链扩展（ERC-4337 账户抽象、跨链结算与行业 RFC 标准）。</li></ul></li><li><strong>架构连续性</strong>：保持 <code>currency-and-multichain-spec.md</code> 作为远期架构参考（Planned / Unscheduled），不破坏当前主线焦点。</li></ol><hr><h2 id="_4-consequences" tabindex="-1">4. Consequences <a class="header-anchor" href="#_4-consequences" aria-label="Permalink to &quot;4. Consequences&quot;">​</a></h2><ul><li><strong>Positive</strong>：全局规划收敛至唯一事实来源，消除了所有历史年份描述冲突；开发主线清晰聚焦高价值业务闭环。</li><li><strong>Compliance</strong>：项目所有文档与规范均对齐最新主线路线图。</li></ul>',19)])])}const m=e(s,[["render",o]]);export{p as __pageData,m as default};
